import csv
from collections import defaultdict

with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    content = f.read()

reader = csv.reader(content.splitlines())
header = next(reader)
indicator_cols = header[3:]

missing_counts = {}
total_cells = 0

for row in reader:
    for i, col in enumerate(indicator_cols):
        if i < len(row):
            cell = row[i]
            total_cells += 1
            if cell.strip() == '':
                missing_counts[col] = missing_counts.get(col, 0) + 1
        else:
            missing_counts[col] = missing_counts.get(col, 0) + 1

missing_rates = {}
for col in indicator_cols:
    missing = missing_counts.get(col, 0)
    rate = missing / total_cells if total_cells > 0 else 0
    missing_rates[col] = rate

print('Indicator columns:', indicator_cols)
print()
for col in indicator_cols:
    print(f'{col}: missing={missing_counts.get(col, 0)}, rate={missing_rates[col]:.6f}')

selected = [col for col in indicator_cols if missing_rates[col] <= 0.30]
print()
print('Selected indicators:', selected)
""}

