import csv

with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    content = f.read()

reader = csv.reader(content.splitlines())
header = next(reader)
indicator_cols = header[3:]

total_cells = 0
missing_counts = {}

for row in reader:
    for i, col in enumerate(indicator_cols):
        if i < len(row):
            cell = row[i]
            total_cells += 1
            if cell.strip() == '':
                missing_counts[col] = missing_counts.get(col, 0) + 1
        else:
            missing_counts[col] = missing_counts.get(col, 0) + 1

print(f'Total cells in indicator columns: {total_cells}')
print(f'Total rows (excluding header): {total_cells // len(indicator_cols)}')
print()
for col in indicator_cols:
    print(f'{col}: missing={missing_counts.get(col, 0)}, rate={missing_counts.get(col, 0)/total_cells:.6f}')
